memory_buffer buffer;
if (fspecs.format == float_format::hex) {
  if (fspecs.sign) buffer.push_back(data::signs[fspecs.sign]);
  auto promoted = promote_float(value);
  snprintf_float(promoted, specs.precision, fspecs, buffer);
  const char* bytes = buffer.data();
  size_t size = buffer.size();
  const char* bytes_begin = bytes;
  const char* bytes_end = bytes + size;
  if (specs.width > 0) {
    unsigned spec_width = to_unsigned(specs.width);
    if (spec_width > size) {
      size_t content_size = size;
      size_t padding = spec_width - content_size;
      const char* shifts = data::left_padding_shifts;
      size_t shift = static_cast<size_t>(shifts[specs.align]);
      size_t left_padding = padding >> shift;
      size_t right_padding = padding - left_padding;
      size_t fill_size = specs.fill.size();
      const Char* fill_data = specs.fill.data();
      size_t padded_size = content_size + padding * fill_size;
      auto it = reserve(out, padded_size);
      size_t filled = 0;
      for (; filled < left_padding; ++filled) {
        const Char* fill_begin = fill_data;
        const Char* fill_end = fill_data + fill_size;
        it = copy_str<Char>(fill_begin, fill_end, it);
      }
      it = copy_str<Char>(bytes_begin, bytes_end, it);
      size_t trailing = right_padding;
      it = fill(it, trailing, specs.fill);
      return base_iterator(out, it);
    }
  }
  auto it = reserve(out, size);
  it = copy_str<Char>(bytes_begin, bytes_end, it);
  return base_iterator(out, it);
}

